    'COPY INTO @' || :tgt || '.APP_STAGE/source/f9758805beab7b69/AGENTS.md FROM (SELECT BASE64_DECODE_STRING(''' || BASE64_ENCODE(BASE64_DECODE_STRING('IyBFZGl0YWJsZSBvbmVzaG90IHNvdXJjZQoKVGhlIGluc3RhbGxlciBjcmVhdGVkIHRoaXMgY3VzdG9tZXItb3duZWQgd29ya3NwYWNlIGFuZCBkZXBsb3ll'
